python3 -c "
from collections import defaultdict
import bs4
with open('archive_top10.html', 'r', encoding='utf-8') as f:
    text = f.read()

soup = bs4.BeautifulSoup(text, 'html.parser')
current_year = None
books = defaultdict(set)

import re

for p in soup.find_all(['button', 'h3', 'li']):
    txt = p.get_text()
    if 'Top 10 Most Challenged' in txt or 'Top 11 Most Challenged' in txt:
        m = re.search(r'2015|2016|2017|2018|2019|2020', txt)
        if m:
            current_year = m.group(0)

    if current_year and getattr(p, 'name', '') == 'li':
        strong = p.find('strong')
        em = p.find('em')
        title = ''
        if em: title = em.get_text().strip()
        elif strong: title = strong.get_text().strip()
        else:
            parts = txt.split(' by ')
            if len(parts) > 1:
                title = parts[0].strip('.0123456789 ')

        if title:
            # normalize
            title = title.replace('Melissa (previously published as George)', 'George')
            if 'George' in title and 'Melissa' not in title and 'Gino' in txt:
                title = 'George'

            books[title].add(current_year)

for title, years in books.items():
    if len(years) > 1:
        print(f'{title}: {sorted(list(years))}')
"
